WITH ord_totals AS (
  SELECT SUM(amount_cents) AS gross_cents FROM orders
  WHERE order_date >= '2026-09-01' AND order_date < '2026-10-01'
), refund_totals AS (
  SELECT SUM(amount_cents) AS refund_cents FROM refunds
  WHERE refund_date >= '2026-09-01' AND refund_date < '2026-10-01'
)
SELECT gross_cents AS gross, refund_cents AS refunds,
       gross_cents - refund_cents AS net FROM ord_totals CROSS JOIN refund_totals;

